-- AUTOMATISCH ERZEUGT aus daten/ (npm run seed) – nicht von Hand bearbeiten.
-- Teil von supabase/seed.sql: Thema 4 „Schule“ – Instrumente, Maßnahmen, Prüfeinheiten, Abdeckung.
-- Nach 0-gemeinsam.sql ausführen. Mehrfach ausführbar, gespielte Runden bleiben erhalten.

begin;

delete from public.massnahmen where thema_id = 4;
delete from public.abdeckung where thema_id = 4;
delete from public.pruef_einheiten where thema_id = 4;

-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (6067, 4, 'Kostenloses Mittagessen in Kitas und Schulen, gemeinsam mit den Ländern', 'Kostenfreies Essen entlastet benachteiligte Familien; Studien finden teils positive, meist kleine Effekte auf Lernen. Finanzierung mit den Ländern ist aufwendig.', 'gemischt', null, 'bund', null, true, null),
  (6068, 4, 'Investitionsprogramm des Bundes für Schulgebäude, ohne genannten Betrag', 'Investitionsmittel setzen direkt am Sanierungsstau an; der Umfang ist nicht beziffert. Der Bund kann Schulbau nur über Finanzhilfen mitfinanzieren.', 'belegt', null, 'bund', null, true, null),
  (6069, 4, 'Verbindliche Sprachstandsfeststellung vor der Einschulung mit Förderpflicht', 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'gemischt', null, 'land', null, true, null),
  (6070, 4, 'Mehr Unterrichtszeit für Deutsch und Mathematik', 'Mehr Unterrichtszeit für Lesen, Schreiben und Rechnen kann Basiskompetenzen stärken; Studien finden Effekte vor allem bei gezielter, gut angeleiteter Übung. Braucht zusätzliche Lehrkräftestunden, die knapp sind.', 'gemischt', null, 'land', null, true, null),
  (6071, 4, 'Mehr Mittel und Personal für Schulen in schwieriger Lage (Sozialindex)', 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'gemischt', null, 'land', null, true, null),
  (6072, 4, 'Verwaltungs-, IT- und Assistenzkräfte an Schulen', 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'gemischt', null, 'land', null, true, null),
  (6073, 4, 'Mehr und praxisnähere Lehramtsausbildung', 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'gemischt', null, 'land', null, true, null),
  (6074, 4, 'Zulagen, Stipendien oder Verpflichtungen für unterversorgte Regionen und Fächer', 'Zulagen, Stipendien oder Verpflichtungen können Lehrkräfte in unterversorgte Regionen oder Schulen lenken; die Gesamtzahl der Lehrkräfte steigt dadurch kaum. Für das Land finanzierbar, aber mit dauerhaften Kosten.', 'gemischt', null, 'land', null, true, null),
  (6075, 4, 'Seiten- und Quereinstieg mit Qualifizierung', 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'gemischt', null, 'land', null, true, null),
  (6076, 4, 'Schulbauprogramm des Landes ohne genannten Betrag', 'Ein Schulbauprogramm setzt direkt am Sanierungsstau an; wie weit es reicht, hängt von Umfang, Baukapazitäten und Kommunen ab. Das Programm nennt keinen Betrag, die Finanzierung muss das Land im Haushalt sichern.', 'belegt', null, 'land', null, true, null),
  (6077, 4, 'Mehr Sprachförderung in Kitas, ohne Förderpflicht', 'Mehr Sprachförderung in Kitas setzt am Sprachförderbedarf an; ohne verbindliche Feststellung und Förderpflicht erreicht sie nicht sicher alle Kinder mit Bedarf. Das Land ist zuständig.', 'gemischt', null, 'land', null, true, null),
  (6078, 4, 'Schulsozialarbeit ausbauen und dauerhaft finanzieren', 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'gemischt', null, 'land', null, true, null),
  (6079, 4, 'Längeres gemeinsames Lernen, mehr Gemeinschaftsschulen', 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'offen', null, 'land', null, true, null),
  (6080, 4, 'Ganztagsangebote an Schulen ausbauen', 'Ganztag kann Kinder aus benachteiligten Familien unterstützen, Effekte auf Leistungen hängen laut Studien stark von der Qualität ab. Der Ausbau braucht Personal und Räume.', 'gemischt', null, 'land', null, true, null),
  (6081, 4, 'Lehrkräfte im Ruhestand zurückgewinnen', 'Pensionierte Lehrkräfte zurückzugewinnen hilft kurzfristig; erfahrungsgemäß kehren nur wenige zurück, eine dauerhafte Lösung ist es nicht. Für das Land leicht umsetzbar.', 'gemischt', null, 'land', null, true, null),
  (6082, 4, 'Leistungsabhängiger Zugang zum Gymnasium', 'Leistungsabhängige Übergänge ins Gymnasium sollen passgenauer fördern; ob die Schulstruktur die Leistungen verbessert, ist in der Forschung nicht entschieden. Das Land kann es im Schulgesetz regeln.', 'offen', null, 'land', null, true, null),
  (6083, 4, 'Handyverbot an Schulen', 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'gemischt', null, 'land', null, true, null),
  (6084, 4, 'Kostenloses Schulessen und Lernmittel aus Landesmitteln', 'Kostenfreies Essen und Lernmittel entlasten benachteiligte Familien; Studien finden teils positive, meist kleine Effekte auf das Lernen. Dauerhafte Kosten für das Land.', 'gemischt', null, 'land', null, true, null),
  (6085, 4, 'Schulsanierung beschleunigen, ohne Umfang und Finanzierung', 'Mehr Tempo bei Schulsanierungen setzt am Sanierungsstau an; das Programm nennt aber weder Umfang noch Finanzierung.', 'gemischt', null, 'land', null, true, null),
  (6086, 4, 'Verbindliches Vorschuljahr mit Sprachbildung', 'Ein verbindliches Vorschuljahr kann Sprachrückstände vor der Einschulung verringern; ohne Feststellung des Förderbedarfs ist die Förderung weniger gezielt. Braucht Fachkräfte in Kitas oder Grundschulen.', 'gemischt', null, 'land', null, true, null),
  (6087, 4, 'Getrennte Sprachklassen vor dem Regelunterricht', 'Getrennte Sprachklassen vor dem Regelunterricht können gezielt Deutsch vermitteln; Studien zu getrenntem und gemeinsamem Unterricht sind gemischt. Braucht zusätzliche Lehrkräfte.', 'gemischt', null, 'land', null, true, null),
  (6088, 4, 'Leichtere Anerkennung ausländischer Lehrkräfte', 'Leichtere Anerkennung ausländischer Lehrkräfte (etwa mit nur einem Fach) erschließt kurzfristig zusätzliche Bewerberinnen und Bewerber; ihre Zahl ist begrenzt, das Sprachniveau bleibt eine Hürde. Das Land ist zuständig.', 'gemischt', null, 'land', null, true, null),
  (8693, 4, 'Kostenfreie schulische Förder- und Nachhilfeangebote flächendeckend (Land)', 'Nachhilfe in Kleingruppen verbessert Leistungen laut Metaanalysen deutlich, vor allem in der Schule und durch geschultes Personal; Umfang und Form sind offen, Personal und dauerhafte Kosten sind die Hürde.', 'belegt', 'https://www.nber.org/papers/w27476', 'land', null, true, 'blind'),
  (8694, 4, 'Kitabesuch ab drei Jahren fördern, Platzausbau vorrangig in Quartieren mit hohem Bedarf (Land)', 'Kitabesuch ab drei verbessert die Schulfähigkeit benachteiligter und zugewanderter Kinder deutlich; wie der Besuch gefördert wird, bleibt offen. Der Ausbau braucht Fachkräfte, die knapp sind.', 'belegt', 'https://iab.de/en/publications/publication/?id=8487991', 'land', null, true, 'blind'),
  (8695, 4, 'Erhebung sprachlicher und mathematischer Defizite vor der Einschulung mit gezielter Förderung (Land)', 'Frühe Erhebung mit gezielter Förderung setzt an Sprach- und Rechenrückständen vor Schulbeginn an; Studien zu vorschulischen Förderprogrammen zeigen unterschiedlich starke Effekte. Braucht Fachkräfte für die Förderung.', 'gemischt', null, 'land', null, true, 'blind')
on conflict (id) do update set thema_id = excluded.thema_id, name = excluded.name, begruendung = excluded.begruendung,
  evidenz = excluded.evidenz, beleg_studie_url = excluded.beleg_studie_url, ebene = excluded.ebene,
  entspricht = excluded.entspricht, ki_entwurf = excluded.ki_entwurf, entwurf_herkunft = excluded.entwurf_herkunft;

delete from public.instrumente where thema_id = 4 and id not in (6067, 6068, 6069, 6070, 6071, 6072, 6073, 6074, 6075, 6076, 6077, 6078, 6079, 6080, 6081, 6082, 6083, 6084, 6085, 6086, 6087, 6088, 8693, 8694, 8695);

insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft) values
  (4001, 4, 11, null, 'Entwicklungsstand aller Drei- bis Vierjährigen nach einheitlichen Standards erfassen', '{404}', null, 1, 2, null, 'Eine frühe Diagnose ist Voraussetzung für Förderung, bewirkt allein aber noch keine. Einheitliche Standards brauchen die Zustimmung der Länder.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=65', null, 'gemischt', '2026-09-28', false, true, null),
  (4002, 4, 11, null, 'Kinder mit Sprachförderbedarf zu einem Vorschulprogramm verpflichten; Bundesprogramm Sprach-Kitas neu starten', '{404}', null, 2, 2, null, 'Verbindliche Förderung vor der Einschulung setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Die Pflicht müssen die Länder regeln, das Bundesprogramm ist finanzierbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=65', null, 'gemischt', '2026-09-28', false, true, null),
  (4003, 4, 11, null, 'Verbindliche Vergleichsarbeiten und Lernstandserhebungen; bundesweit vergleichbares Abitur', '{403}', null, 1, 1, null, 'Lernstandserhebungen machen Rückstände sichtbar, beheben sie aber nicht selbst; die Forschung zu Wirkungen von Leistungsvergleichen ist uneinheitlich. Das regeln allein die Länder.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=65', null, 'gemischt', '2026-09-28', false, true, null),
  (4004, 4, 11, null, 'Ganztagsangebote für Grundschulkinder ausbauen, mit Schwerpunkt auf Lesen, Schreiben und Rechnen', '{403,405}', null, 1, 3, null, 'Ganztag kann Kinder aus benachteiligten Familien unterstützen, Effekte auf Leistungen hängen laut Studien stark von der Qualität ab. Der Bund fördert den Ausbau bereits.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=65', null, 'gemischt', '2026-09-28', false, true, null),
  (4011, 4, 12, null, 'Fachkräfteoffensive für Kitas und Schulen mit allen Ländern: mehr Ausbildungsplätze, Quereinstieg, multiprofessionelle Teams', '{401}', null, 2, 2, null, 'Mehr Ausbildungskapazität und Quereinstieg setzen am Lehrkräftemangel an, wirken aber erst mittelfristig; die Qualität des Quereinstiegs ist umstritten. Braucht eine Vereinbarung mit allen Ländern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=15', null, 'gemischt', '2026-09-28', false, true, null),
  (4012, 4, 12, null, 'Entwicklungsstand aller Kinder mit vier Jahren und bei der Einschulung feststellen, bei Bedarf verbindliche Förderung', '{404}', null, 2, 2, null, 'Frühe Feststellung mit verbindlichem Förderangebot setzt direkt am Sprachförderbedarf an; Studien zeigen unterschiedlich starke Effekte. Umsetzung liegt bei den Ländern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=15', null, 'gemischt', '2026-09-28', false, true, null),
  (4013, 4, 12, null, 'Startchancenprogramm an Schulen schrittweise ausbauen und eines für Kitas in benachteiligten Lagen schaffen', '{405,403}', null, 2, 2, null, 'Geld gezielt nach sozialer Lage zu verteilen setzt an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Programms läuft noch, internationale Erfahrungen sind gemischt. Ausbau braucht zusätzliche Mittel von Bund und Ländern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=15', null, 'gemischt', '2026-09-28', false, true, null),
  (4014, 4, 12, null, 'Schuldenregel reformieren, damit Investitionen etwa in Schulgebäude möglich werden; auch Länder sollen Kredite aufnehmen dürfen', '{402}', null, 2, 1, null, 'Mehr Investitionsspielraum kann den Sanierungsstau abbauen, wenn das Geld bei Ländern und Kommunen ankommt. Die Reform erfordert eine Grundgesetzänderung mit Zweidrittelmehrheit.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=17', null, 'belegt', '2026-09-28', false, true, null),
  (4015, 4, 12, null, 'Gesundes, kostenloses Mittagessen für alle Kita-Kinder und Schülerinnen und Schüler, gemeinsam mit den Ländern', '{405}', 6067, 1, 2, null, 'Kostenfreies Essen entlastet benachteiligte Familien; Studien finden teils positive, meist kleine Effekte auf Lernen. Finanzierung mit den Ländern ist aufwendig.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=27', null, 'gemischt', '2026-09-28', false, true, null),
  (4021, 4, 13, null, '„Zukunftsinvestitionsprogramm Bildung“ mit Ländern und Kommunen, unter anderem für moderne, sanierte Schulgebäude', '{402}', 6068, 2, 2, null, 'Investitionsmittel setzen direkt am Sanierungsstau an; der Umfang ist nicht beziffert. Der Bund kann Schulbau nur über Finanzhilfen mitfinanzieren.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=77', null, 'belegt', '2026-09-28', false, true, null),
  (4022, 4, 13, null, 'Mehr Stellen für Schulsozialarbeit, Schulpsychologie und Inklusion; Schwerpunkt auf Basiskompetenzen', '{403}', null, 2, 1, null, 'Ein Fokus auf Basiskompetenzen und Unterstützung durch Fachpersonal setzt an Lernrückständen an; die Wirkung multiprofessioneller Teams ist unterschiedlich belegt. Stellen schaffen die Länder, und Fachpersonal ist knapp.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=77', null, 'gemischt', '2026-09-28', false, true, null),
  (4023, 4, 13, null, 'Länder bei der Lehrkräftegewinnung unterstützen: duale Studiengänge, Ein-Fach-Lehrkräfte, Wege für Quer- und Seiteneinstieg', '{401}', null, 2, 2, null, 'Neue Zugangswege erhöhen das Angebot an Lehrkräften, wirken aber erst mittelfristig; die Qualität des Quereinstiegs ist umstritten. Umsetzung liegt bei den Ländern, der Bund kann unterstützen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=77', null, 'gemischt', '2026-09-28', false, true, null),
  (4024, 4, 13, null, 'Bildungsmittel nach tatsächlichem Bedarf statt nach Königsteiner Schlüssel verteilen; Bildungsoffensive für mehr Schulen', '{405}', null, 2, 2, null, 'Bedarfsorientierte Verteilung lenkt Mittel zu Schulen mit vielen benachteiligten Kindern; internationale Erfahrungen damit sind gemischt. Braucht Einigung mit den Ländern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=77', null, 'gemischt', '2026-09-28', false, true, null),
  (4025, 4, 13, null, 'Sprachförderung als durchgängiger Prozess von der Kita bis in die Ausbildung', '{404}', null, 1, 2, null, 'Durchgängige Sprachbildung setzt am Förderbedarf an, das Programm nennt aber kein konkretes Instrument wie Tests oder verbindliche Förderung. Umsetzung liegt bei den Ländern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=78', null, 'gemischt', '2026-09-28', false, true, null),
  (4031, 4, 14, null, 'Bundesweit verpflichtende Sprachtests im Vorschulalter; bei Förderbedarf verpflichtende Sprachförderung zwei Jahre vor der Schule', '{404}', null, 2, 2, null, 'Verbindliche Tests mit verpflichtender Förderung setzen direkt am Sprachförderbedarf an; Studien zeigen unterschiedlich starke Effekte, ein späterer Schuleintritt ist umstritten. Umsetzung liegt bei den Ländern.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=7', null, 'gemischt', '2026-09-28', false, true, null),
  (4032, 4, 14, null, 'Startchancen-Programm für Kitas mit vielen sozial benachteiligten Kindern', '{405}', null, 2, 2, null, 'Gezielte Mittel für Kitas in benachteiligten Lagen setzen früh an der Kopplung von Herkunft und Bildungserfolg an; die Evidenz zu solchen Programmen ist gemischt. Braucht Mittel und Einigung mit den Ländern.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=7', null, 'gemischt', '2026-09-28', false, true, null),
  (4033, 4, 14, null, 'Sanierung der Schulgebäude; Digitalpakt 2.0 von Bund und Ländern', '{402}', null, 2, 1, null, 'Die Forderung setzt am Sanierungsstau an, nennt aber weder Umfang noch Finanzierung. Schulbau ist Aufgabe von Ländern und Kommunen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=8', null, 'belegt', '2026-09-28', false, true, null),
  (4034, 4, 14, null, 'Lehrberuf attraktiver machen: bessere Arbeitsbedingungen, leistungsorientierte Bezahlung, duales Lehramtsstudium, Mobilitätsgarantie', '{401}', null, 2, 2, null, 'Attraktivere Bedingungen und ein praxisnäheres Studium können mehr Menschen für den Beruf gewinnen, wirken aber erst mittelfristig; die Mobilitätsgarantie verteilt vorhandene Lehrkräfte nur um. Umsetzung liegt bei den Ländern.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=9', null, 'gemischt', '2026-09-28', false, true, null),
  (4035, 4, 14, null, 'Bundesweit einheitliche Qualitätsstandards von der Kita bis zum Abschluss, Deutschland-Abitur und Notenpflicht ab Klasse 3', '{403}', null, 1, 1, null, 'Einheitliche Standards und Prüfungen machen Leistungen vergleichbar, beheben Rückstände aber nicht selbst; die Wirkung ist in der Forschung umstritten. Braucht eine Reform des Bildungsföderalismus.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=8', null, 'gemischt', '2026-09-28', false, true, null),
  (4036, 4, 14, null, 'Mehr Eigenständigkeit für Schulen mit frei einsetzbarem Chancenbudget', '{403}', null, 1, 2, null, 'Mehr Autonomie kann Schulen helfen, auf Rückstände zu reagieren; Studien zeigen positive Effekte vor allem zusammen mit Leistungsvergleichen. Das Budget ist nicht nach sozialer Lage gezielt.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=9', null, 'gemischt', '2026-09-28', false, true, null),
  (4041, 4, 15, null, 'Bedarfsorientierte Vorschule, damit alle Kinder dem Unterricht folgen können', '{404}', null, 2, 2, null, 'Eine Vorschule für Kinder mit Rückständen setzt direkt am Sprachförderbedarf an; Studien zu Vorschulprogrammen zeigen unterschiedlich starke Effekte. Umsetzung liegt bei den Ländern.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=160', null, 'gemischt', '2026-09-28', false, true, null),
  (4042, 4, 15, null, 'Verpflichtender Deutschunterricht für Kinder, die nicht genug Deutsch für den Regelunterricht sprechen', '{404}', null, 2, 2, null, 'Gezielter Deutschunterricht setzt am Sprachförderbedarf an; ob getrennter oder integrierter Unterricht besser wirkt, ist in der Forschung umstritten. Umsetzung liegt bei den Ländern.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=162', null, 'gemischt', '2026-09-28', false, true, null),
  (4043, 4, 15, null, 'Klassenstärken an allen Schulformen verringern', '{403}', null, 1, 1, null, 'Kleinere Klassen helfen laut Studien vor allem in den ersten Schuljahren, sonst sind die Effekte gering. Sie brauchen deutlich mehr Lehrkräfte, die schon jetzt fehlen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=159', null, 'gemischt', '2026-09-28', false, true, null),
  (4044, 4, 15, null, 'Bildungsstandards aller Schulformen anheben statt Leistungsanforderungen zu senken', '{403}', null, 1, 1, null, 'Höhere Standards benennen ein Ziel, sagen aber nicht, wie Rückstände aufgeholt werden. Die Standards legen allein die Länder in der Kultusministerkonferenz fest.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=159', null, 'offen', '2026-09-28', false, true, null),
  (4051, 4, 16, null, 'Vertretungsreserve von zehn Prozent; Anerkennung zugewanderter Lehrkräfte und Ausbildung von Quer- und Seiteneinsteigern', '{401}', null, 2, 2, null, 'Anerkennung und Quereinstieg erhöhen das Angebot an Lehrkräften; eine Vertretungsreserve setzt voraus, dass zusätzliche Lehrkräfte gefunden werden. Umsetzung liegt bei den Ländern.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', null, 'gemischt', '2026-09-28', false, true, null),
  (4052, 4, 16, null, '100-Milliarden-Euro-Sondervermögen des Bundes für Sanierung und Modernisierung von Bildungseinrichtungen, später Vermögensteuer', '{402}', null, 2, 1, null, 'Ein großes Investitionsprogramm setzt direkt am Sanierungsstau an. Ein kreditfinanziertes Sondervermögen und die Vermögensteuer sind rechtlich und politisch mit großen Hürden verbunden.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', null, 'belegt', '2026-09-28', false, true, null),
  (4053, 4, 16, null, 'Kostenlose Lernmittel, Verpflegung und Schülerbeförderung', '{405}', null, 1, 2, null, 'Kostenfreiheit entlastet benachteiligte Familien; Wirkungen auf den Schulerfolg sind meist klein. Braucht Mittel von Bund, Ländern und Kommunen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', null, 'gemischt', '2026-09-28', false, true, null),
  (4054, 4, 16, null, 'Hausaufgaben abschaffen, Üben findet in der Schule statt', '{405}', null, 1, 1, null, 'Üben in der Schule kann Unterschiede durch häusliche Unterstützung verringern; Hausaufgaben haben laut Studien in höheren Klassen aber positive Effekte. Regelungen dazu treffen die Länder.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', null, 'gemischt', '2026-09-28', false, true, null),
  (4055, 4, 16, null, 'Eine ganztägige Gemeinschaftsschule für alle statt des gegliederten Schulsystems', '{405}', null, 2, 1, null, 'Längeres gemeinsames Lernen soll die Kopplung von Herkunft und Schulerfolg verringern; internationale Studien stützen das teilweise, deutsche Vergleiche sind uneinheitlich. Die Schulstruktur bestimmen die Länder.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=39', null, 'gemischt', '2026-09-28', false, true, null),
  (4056, 4, 16, null, 'Mehr Pädagoginnen und Pädagogen pro Klasse; Schulpsychologie und Sozialarbeit an jeder Schule', '{403}', null, 2, 1, null, 'Mehr Personal pro Klasse ermöglicht individuelle Förderung; die Wirkung ist unterschiedlich belegt. Es braucht zusätzliches Personal, das schon jetzt fehlt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=39', null, 'gemischt', '2026-09-28', false, true, null),
  (4057, 4, 16, null, 'Bundesprogramm für Lehrkräfte in Deutsch als Zweitsprache und Sprachkurse auch für Eltern und Geschwister', '{404}', null, 2, 2, null, 'Mehr qualifizierte Sprachförderung in Schulen und für Familien setzt am Förderbedarf an; Studien zeigen unterschiedlich starke Effekte. Ein Bundesprogramm ist mit den Ländern umsetzbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=39', null, 'gemischt', '2026-09-28', false, true, null),
  (4061, 4, 17, null, 'Länder bei der Ausbildung von mehr Lehrkräften unterstützen; duale Lehrerausbildung; bessere Bedingungen für Seiteneinsteiger; Entlastung durch Unterstützungsteams', '{401}', null, 2, 2, null, 'Mehr Ausbildung und Seiteneinstieg setzen am Lehrkräftemangel an, wirken aber erst mittelfristig; die Qualität des Seiteneinstiegs ist umstritten. Umsetzung liegt bei den Ländern, der Bund kann unterstützen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=25', null, 'gemischt', '2026-09-29', false, true, null),
  (4062, 4, 17, null, 'Investitionen unter anderem in Schulen aus der Schuldenbremse ausklammern', '{402}', null, 2, 1, null, 'Mehr Investitionsspielraum kann den Sanierungsstau abbauen, wenn das Geld bei Ländern und Kommunen ankommt. Die Änderung der Schuldenbremse erfordert eine Grundgesetzänderung mit Zweidrittelmehrheit.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=15', null, 'belegt', '2026-09-29', false, true, null),
  (4063, 4, 17, null, 'Investitionsprogramm „Kinder und Bildung“ für marode Bildungs- und Betreuungseinrichtungen in Städten und Gemeinden', '{402}', 6068, 2, 2, null, 'Investitionsmittel setzen direkt am Sanierungsstau an; der Umfang ist nicht beziffert. Der Bund kann Schulbau nur über Finanzhilfen mitfinanzieren.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=32', null, 'belegt', '2026-09-29', false, true, null),
  (4064, 4, 17, null, 'Verpflichtender Deutschtest ab drei Jahren; bei Defiziten verpflichtender, beitragsfreier Kita-Besuch mit Sprachbildung', '{404}', null, 2, 2, null, 'Frühe verbindliche Tests mit verpflichtender Förderung setzen direkt am Sprachförderbedarf an; Studien zeigen unterschiedlich starke Effekte. Umsetzung liegt bei den Ländern.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=24', null, 'gemischt', '2026-09-29', false, true, null),
  (4065, 4, 17, null, 'Ganztagsschulen sowie Hort- und Hausaufgabenbetreuung ausbauen, damit Kinder weniger von der Unterstützung der Eltern abhängen', '{405}', null, 1, 2, null, 'Ganztag kann Kinder aus benachteiligten Familien unterstützen, Effekte auf Leistungen hängen laut Studien stark von der Qualität ab. Der Bund fördert bisher nur den Ganztag an Grundschulen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=24', null, 'gemischt', '2026-09-29', false, true, null),
  (4066, 4, 17, null, 'Längeres gemeinsames Lernen und ein durchlässiges Schulsystem statt früher Aufteilung nach Klasse 4', '{405}', null, 2, 1, null, 'Später aufzuteilen soll die Kopplung von Herkunft und Schulerfolg verringern; internationale Studien stützen das teilweise, deutsche Vergleiche sind uneinheitlich. Die Schulstruktur bestimmen allein die Länder.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=24', null, 'gemischt', '2026-09-29', false, true, null),
  (4067, 4, 17, null, 'Grundschule auf Lesen, Schreiben und Rechnen konzentrieren; Handys und Tablets bis Ende der Grundschule aus dem Unterricht', '{403}', null, 1, 1, null, 'Ein Fokus auf Basiskompetenzen setzt an Lernrückständen an; zur Wirkung von Geräteverboten ist die Forschung uneinheitlich. Das regeln allein die Länder.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=24', null, 'gemischt', '2026-09-29', false, true, null),
  (4068, 4, 17, null, 'Kostenloses, gesundes Mittagessen in Kitas und Schulen', '{405}', 6067, 1, 2, null, 'Kostenfreies Essen entlastet benachteiligte Familien; Studien finden teils positive, meist kleine Effekte auf Lernen. Finanzierung mit den Ländern ist aufwendig.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=31', null, 'gemischt', '2026-09-29', false, true, null),
  (4101, 4, 11, 'ST', 'Verbindliche Sprachstandsfeststellung im vierten Lebensjahr; letztes Kita-Jahr als Vorschuljahr mit Förderung', '{404}', 6069, 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=48', null, 'gemischt', '2026-09-29', false, true, null),
  (4102, 4, 11, 'ST', 'Unterricht in Mathematik und Deutsch an Grundschulen ausbauen', '{403}', 6070, 2, 2, null, 'Mehr Unterrichtszeit für Lesen, Schreiben und Rechnen kann Basiskompetenzen stärken; Studien finden Effekte vor allem bei gezielter, gut angeleiteter Übung. Braucht zusätzliche Lehrkräftestunden, die knapp sind.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=21', null, 'gemischt', '2026-09-29', false, true, null),
  (4103, 4, 11, 'ST', 'Schulen in sozial herausfordernden Lagen mit zusätzlichem Personal, Förderangeboten und Ausstattung unterstützen', '{405}', 6071, 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=22', null, 'gemischt', '2026-09-29', false, true, null),
  (4104, 4, 11, 'ST', 'Schulen dürfen Vertretungspersonal und Unterstützungskräfte einstellen; Unterstützung in Unterricht und Verwaltung ausbauen', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=20', null, 'gemischt', '2026-09-29', false, true, null),
  (4105, 4, 11, 'ST', 'Duales Lehramtsstudium verstetigen und zum Standard ausbauen; Hochschulen an Absolventenzahlen messen', '{401}', 6073, 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=24', null, 'gemischt', '2026-09-29', false, true, null),
  (4106, 4, 11, 'ST', 'Zulage für Referendare außerhalb der Oberzentren; Stipendium für Lehramtsstudierende; Wege für Seiteneinsteiger', '{401}', 6074, 1, 2, null, 'Zulagen, Stipendien oder Verpflichtungen können Lehrkräfte in unterversorgte Regionen oder Schulen lenken; die Gesamtzahl der Lehrkräfte steigt dadurch kaum. Für das Land finanzierbar, aber mit dauerhaften Kosten.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=24', null, 'gemischt', '2026-09-29', false, true, null),
  (4107, 4, 11, 'ST', 'Klare Aus- und Fortbildungswege für Seiteneinsteigerinnen und Seiteneinsteiger', '{401}', 6075, 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=24', null, 'gemischt', '2026-09-29', false, true, null),
  (4111, 4, 12, 'ST', 'Landesschulbauprogramm', '{402}', 6076, 2, 2, null, 'Ein Schulbauprogramm setzt direkt am Sanierungsstau an; wie weit es reicht, hängt von Umfang, Baukapazitäten und Kommunen ab. Das Programm nennt keinen Betrag, die Finanzierung muss das Land im Haushalt sichern.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=18', null, 'belegt', '2026-09-29', false, true, null),
  (4112, 4, 12, 'ST', 'Mehr Zeit im Stundenplan für Rechnen, Lesen, Vorlesen, Üben und Wiederholen', '{403}', 6070, 2, 2, null, 'Mehr Unterrichtszeit für Lesen, Schreiben und Rechnen kann Basiskompetenzen stärken; Studien finden Effekte vor allem bei gezielter, gut angeleiteter Übung. Braucht zusätzliche Lehrkräftestunden, die knapp sind.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=18', null, 'gemischt', '2026-09-29', false, true, null),
  (4113, 4, 12, 'ST', 'Duales Studium und Praxisanteile in der Lehramtsausbildung ausbauen; 1.200 Studienplätze halten', '{401}', 6073, 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=18', null, 'gemischt', '2026-09-29', false, true, null),
  (4114, 4, 12, 'ST', 'Seiteneinsteigende qualifiziert begleiten und fair bezahlen', '{401}', 6075, 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=18', null, 'gemischt', '2026-09-29', false, true, null),
  (4115, 4, 12, 'ST', 'Multiprofessionelle Teams mit Fachkräften für Verwaltung und digitale Ausstattung', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=18', null, 'gemischt', '2026-09-29', false, true, null),
  (4116, 4, 12, 'ST', 'Frühere Schuleingangsuntersuchungen und stärkere Sprachförderung', '{404}', 6077, 1, 3, null, 'Mehr Sprachförderung in Kitas setzt am Sprachförderbedarf an; ohne verbindliche Feststellung und Förderpflicht erreicht sie nicht sicher alle Kinder mit Bedarf. Das Land ist zuständig.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=17', null, 'gemischt', '2026-09-29', false, true, null),
  (4117, 4, 12, 'ST', 'Gezielte sachliche und personelle Unterstützung für Schulen mit besonderen sozialen Herausforderungen', '{405}', 6071, 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=19', null, 'gemischt', '2026-09-29', false, true, null),
  (4118, 4, 12, 'ST', 'Schulsozialarbeit dauerhaft aus Landesmitteln finanzieren und ausbauen', '{405}', 6078, 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=18', null, 'gemischt', '2026-09-29', false, true, null),
  (4119, 4, 12, 'ST', 'Mittelfristig zwei weiterführende Schulformen: Gymnasium und Gemeinschaftsschule', '{405}', 6079, 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=18', null, 'offen', '2026-09-29', false, true, null),
  (4121, 4, 13, 'ST', 'Umfassendes Schulbauprogramm für Sanierungen; Sofortprogramm für Schultoiletten', '{402}', 6076, 2, 2, null, 'Ein Schulbauprogramm setzt direkt am Sanierungsstau an; wie weit es reicht, hängt von Umfang, Baukapazitäten und Kommunen ab. Das Programm nennt keinen Betrag, die Finanzierung muss das Land im Haushalt sichern.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=62', null, 'belegt', '2026-09-29', false, true, null),
  (4122, 4, 13, 'ST', 'Landesspezifischer Schulsozialindex für die gezielte Verteilung zusätzlicher Mittel', '{405}', 6071, 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=62', null, 'gemischt', '2026-09-29', false, true, null),
  (4123, 4, 13, 'ST', 'Landesweit verbindliche Sprachstandsfeststellung in Kitas', '{404}', 6069, 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=57', null, 'gemischt', '2026-09-29', false, true, null),
  (4124, 4, 13, 'ST', 'Seiteneinsteiger berufsbegleitend qualifizieren; Ein-Fach-Lehrkräfte zulassen', '{401}', 6075, 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=61', null, 'gemischt', '2026-09-29', false, true, null),
  (4125, 4, 13, 'ST', 'Lehramtsstudiengänge dauerhaft ausbauen; duales Lehramtsstudium an beiden Universitäten', '{401}', 6073, 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=61', null, 'gemischt', '2026-09-29', false, true, null),
  (4126, 4, 13, 'ST', 'Gehaltszuschläge für Lehrkräfte in strukturschwachen Regionen, belasteten Schulformen und Mangelfächern', '{401}', 6074, 1, 2, null, 'Zulagen, Stipendien oder Verpflichtungen können Lehrkräfte in unterversorgte Regionen oder Schulen lenken; die Gesamtzahl der Lehrkräfte steigt dadurch kaum. Für das Land finanzierbar, aber mit dauerhaften Kosten.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=61', null, 'gemischt', '2026-09-29', false, true, null),
  (4127, 4, 13, 'ST', 'Multiprofessionelle Teams und flächendeckend wieder Schulsekretariate', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=60', null, 'gemischt', '2026-09-29', false, true, null),
  (4128, 4, 13, 'ST', 'Gemeinsame Grundschulzeit bis Klasse 6; Gemeinschaftsschulen statt Sekundarschulen', '{405}', 6079, 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=59', null, 'offen', '2026-09-29', false, true, null),
  (4129, 4, 13, 'ST', 'Alle allgemeinbildenden Schulen zu Ganztagsschulen; kostenfreie Lernmittel und Mittagessen', '{405}', 6080, 1, 2, null, 'Ganztag kann Kinder aus benachteiligten Familien unterstützen, Effekte auf Leistungen hängen laut Studien stark von der Qualität ab. Der Ausbau braucht Personal und Räume.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=59', null, 'gemischt', '2026-09-29', false, true, null),
  (4130, 4, 13, 'ST', 'An jeder Schule mindestens eine fest angestellte Schulsozialarbeiterin oder ein Schulsozialarbeiter', '{405}', 6078, 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=62', null, 'gemischt', '2026-09-29', false, true, null),
  (4131, 4, 14, 'ST', 'Verbindliche Sprachstandsfeststellung mit drei Jahren; Defizite bis Schulbeginn aufholen', '{404}', 6069, 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=24', null, 'gemischt', '2026-09-29', false, true, null),
  (4132, 4, 14, 'ST', 'Verbindliches 1,5-jähriges Qualifizierungsprogramm für Seiteneinsteiger', '{401}', 6075, 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=30', null, 'gemischt', '2026-09-29', false, true, null),
  (4133, 4, 14, 'ST', 'Zugang zum Lehramtsstudium erweitern, etwa mit Fachhochschulreife; Bewerber mit Berufserfahrung zulassen', '{401}', 6073, 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=30', null, 'gemischt', '2026-09-29', false, true, null),
  (4134, 4, 14, 'ST', 'Weiterhin Unterstützungskräfte einstellen, um Lehrkräfte zu entlasten', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=30', null, 'gemischt', '2026-09-29', false, true, null),
  (4135, 4, 14, 'ST', 'Public-Private-Partnership-Modelle für Bau und Sanierung von Schulen', '{402}', null, 1, 2, null, 'Private Partner können Bau und Sanierung beschleunigen; Rechnungshöfe fanden solche Projekte aber oft teurer als konventionelle. Das Land kann Kommunen dabei unterstützen, zusätzliches Geld nennt das Programm nicht.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=29', null, 'gemischt', '2026-09-29', false, true, null),
  (4136, 4, 14, 'ST', 'Datengestützte Förderung: Lern- und Entwicklungsstände früh erkennen und in Förderung übersetzen', '{403}', null, 1, 3, null, 'Regelmäßige Lernstandserhebungen machen Rückstände sichtbar; ob sie wirken, hängt von der Förderung danach ab, die Forschung ist uneinheitlich. Das Land kann das selbst einführen.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=26', null, 'gemischt', '2026-09-29', false, true, null),
  (4137, 4, 14, 'ST', 'Landeseinheitlicher Schülerkostensatz, der auch einen Sozialindex berücksichtigt', '{405}', null, 1, 2, null, 'Ein einheitlicher Kostensatz je Schüler mit Sozialindex kann Mittel gerechter verteilen; wie stark er Schulen in schwieriger Lage besserstellt, lässt das Programm offen. Das Land kann das regeln, Mehrkosten sind möglich.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=28', null, 'offen', '2026-09-29', false, true, null),
  (4141, 4, 15, 'ST', 'Pensionierte und bald pensionierte Lehrkräfte ansprechen, damit sie weiter unterrichten', '{401}', 6081, 1, 3, null, 'Pensionierte Lehrkräfte zurückzugewinnen hilft kurzfristig; erfahrungsgemäß kehren nur wenige zurück, eine dauerhafte Lösung ist es nicht. Für das Land leicht umsetzbar.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=83', null, 'gemischt', '2026-09-29', false, true, null),
  (4142, 4, 15, 'ST', 'Bundesweite Anwerbekampagne für Lehrkräfte; Schulbetrieb entbürokratisieren', '{401}', null, 1, 2, null, 'Eine Anwerbekampagne kann Lehrkräfte aus anderen Ländern gewinnen; sie konkurrieren aber alle um dieselben knappen Lehrkräfte, die Gesamtzahl steigt nicht. Für das Land umsetzbar.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=83', null, 'gemischt', '2026-09-29', false, true, null),
  (4143, 4, 15, 'ST', 'Pädagogische Hochschule für die Ausbildung aller Grund- und Sekundarschullehrkräfte', '{401}', null, 1, 2, null, 'Eine Pädagogische Hochschule bündelt die Ausbildung, schafft aber für sich genommen keine zusätzlichen Studienplätze; ob sie mehr Absolventen bringt, ist offen. Die Gründung braucht mehrere Jahre.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=84', null, 'offen', '2026-09-29', false, true, null),
  (4144, 4, 15, 'ST', 'Verbindliche Schullaufbahnempfehlung nach Klasse 4 auf Basis zentraler Klassenarbeiten', '{403}', 6082, 1, 3, null, 'Leistungsabhängige Übergänge ins Gymnasium sollen passgenauer fördern; ob die Schulstruktur die Leistungen verbessert, ist in der Forschung nicht entschieden. Das Land kann es im Schulgesetz regeln.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=73', null, 'offen', '2026-09-29', false, true, null),
  (4145, 4, 15, 'ST', 'Smartphone-Nutzung bis einschließlich Klasse 10 untersagen', '{403}', 6083, 1, 3, null, 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=79', null, 'gemischt', '2026-09-29', false, true, null),
  (4146, 4, 15, 'ST', 'Mehr Vorlesen in der vorschulischen Bildung', '{404}', null, 1, 3, null, 'Vorlesen fördert die Sprachentwicklung; ohne Feststellung des Förderbedarfs erreicht es Kinder mit Sprachförderbedarf aber nicht gezielt. Das Land kann das in den Bildungsplan aufnehmen.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=20', null, 'offen', '2026-09-29', false, true, null),
  (4151, 4, 16, 'ST', 'Lehramtsausbildung in Magdeburg um 200 Erstsemesterplätze erweitern, auch dual mit Bindung ans Land', '{401}', 6073, 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=34', null, 'gemischt', '2026-09-29', false, true, null),
  (4152, 4, 16, 'ST', 'Seiteneinstieg unterstützen: Entlastung im ersten Jahr, mehr Fortbildung, Vorbereitungsdienst auch mit einem Fach', '{401}', 6075, 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=34', null, 'gemischt', '2026-09-29', false, true, null),
  (4153, 4, 16, 'ST', 'Schulverwaltungs- und Digitalassistenzen bedarfsdeckend einsetzen', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=34', null, 'gemischt', '2026-09-29', false, true, null),
  (4154, 4, 16, 'ST', 'Seminare für den Vorbereitungsdienst in der Fläche; Anwärtersonderbezüge', '{401}', 6074, 1, 2, null, 'Zulagen, Stipendien oder Verpflichtungen können Lehrkräfte in unterversorgte Regionen oder Schulen lenken; die Gesamtzahl der Lehrkräfte steigt dadurch kaum. Für das Land finanzierbar, aber mit dauerhaften Kosten.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=34', null, 'gemischt', '2026-09-29', false, true, null),
  (4155, 4, 16, 'ST', 'Schulbauprogramm des Landes und deutlich höhere Finanzzuweisungen an Kommunen für Bau und Sanierung', '{402}', 6076, 2, 2, null, 'Ein Schulbauprogramm setzt direkt am Sanierungsstau an; wie weit es reicht, hängt von Umfang, Baukapazitäten und Kommunen ab. Das Programm nennt keinen Betrag, die Finanzierung muss das Land im Haushalt sichern.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=33', null, 'belegt', '2026-09-29', false, true, null),
  (4156, 4, 16, 'ST', 'Sprachförderung ab der Kita', '{404}', 6077, 1, 3, null, 'Mehr Sprachförderung in Kitas setzt am Sprachförderbedarf an; ohne verbindliche Feststellung und Förderpflicht erreicht sie nicht sicher alle Kinder mit Bedarf. Das Land ist zuständig.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=99', null, 'gemischt', '2026-09-29', false, true, null),
  (4157, 4, 16, 'ST', 'Schulsozialarbeit gesetzlich verankern: eine Stelle je 150 Schüler, rund 1.200 Vollzeitstellen', '{405}', 6078, 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=28', null, 'gemischt', '2026-09-29', false, true, null),
  (4158, 4, 16, 'ST', 'Mittelfristig ein Schulsystem aus Gemeinschaftsschulen und Gymnasien', '{405}', 6079, 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=31', null, 'offen', '2026-09-29', false, true, null),
  (4159, 4, 16, 'ST', 'Ganztagsangebote an allen weiterführenden Schulen ausbauen', '{405}', 6080, 1, 2, null, 'Ganztag kann Kinder aus benachteiligten Familien unterstützen, Effekte auf Leistungen hängen laut Studien stark von der Qualität ab. Der Ausbau braucht Personal und Räume.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=32', null, 'gemischt', '2026-09-29', false, true, null),
  (4161, 4, 17, 'ST', 'Mehr Lehramtsstudienplätze; Praxisbezug und duales Lehramtsstudium ausbauen', '{401}', 6073, 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=52', null, 'gemischt', '2026-09-29', false, true, null),
  (4162, 4, 17, 'ST', 'Allen Lehramtsabsolventen ein Stellenangebot im Schuldienst machen', '{401}', null, 1, 3, null, 'Ein sicheres Stellenangebot kann Absolventen im Land halten; die Zahl der Absolventen steigt dadurch nicht. Für das Land umsetzbar.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=52', null, 'gemischt', '2026-09-29', false, true, null),
  (4163, 4, 17, 'ST', 'Multiprofessionelle Teams mit Verwaltungspersonal, IT-Unterstützung und Lehrerassistenzen als Standard', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=48', null, 'gemischt', '2026-09-29', false, true, null),
  (4164, 4, 17, 'ST', 'Verbindliche Sprachstandserhebungen vor Schuleintritt; frühzeitige Sprachförderung ausbauen', '{404}', 6069, 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=46', null, 'gemischt', '2026-09-29', false, true, null),
  (4165, 4, 17, 'ST', 'Verbindliches Smartphone-Verbot im Schulalltag', '{403}', 6083, 1, 3, null, 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=45', null, 'gemischt', '2026-09-29', false, true, null),
  (4166, 4, 17, 'ST', 'Längeres gemeinsames Lernen bis Klasse 6, perspektivisch bis Klasse 8', '{405}', 6079, 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=45', null, 'offen', '2026-09-29', false, true, null),
  (4167, 4, 17, 'ST', 'Mindestens eine Schulsozialarbeiterstelle an jeder Schule', '{405}', 6078, 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=47', null, 'gemischt', '2026-09-29', false, true, null),
  (4168, 4, 17, 'ST', 'Landeseigenes Ganztagsförderprogramm und Qualitätsoffensive „Ganztag 2030“', '{405}', 6080, 1, 2, null, 'Ganztag kann Kinder aus benachteiligten Familien unterstützen, Effekte auf Leistungen hängen laut Studien stark von der Qualität ab. Der Ausbau braucht Personal und Räume.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=48', null, 'gemischt', '2026-09-29', false, true, null),
  (4169, 4, 17, 'ST', 'Kostenfreie, gesunde Verpflegung in Kitas und Schulen', '{405}', 6084, 1, 2, null, 'Kostenfreies Essen und Lernmittel entlasten benachteiligte Familien; Studien finden teils positive, meist kleine Effekte auf das Lernen. Dauerhafte Kosten für das Land.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=49', null, 'gemischt', '2026-09-29', false, true, null),
  (4201, 4, 11, 'MV', 'Verpflichtende Sprachstandsfeststellung mit vier bis fünf Jahren; bei Bedarf verpflichtende Förderung in Kita oder Vorschulklasse', '{404}', 6069, 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=46', null, 'gemischt', '2026-09-29', false, true, null),
  (4202, 4, 11, 'MV', 'Ressourcen an Grundschulen nach Problemlagen zuweisen, Schulen in benachteiligten Gebieten stärken', '{405}', 6071, 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=47', null, 'gemischt', '2026-09-29', false, true, null),
  (4203, 4, 11, 'MV', 'Lehrkräfte im Ruhestand für den Wiedereinstieg motivieren', '{401}', 6081, 1, 3, null, 'Pensionierte Lehrkräfte zurückzugewinnen hilft kurzfristig; erfahrungsgemäß kehren nur wenige zurück, eine dauerhafte Lösung ist es nicht. Für das Land leicht umsetzbar.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=47', null, 'gemischt', '2026-09-29', false, true, null),
  (4204, 4, 11, 'MV', 'Pädagogische Fachkräfte und multiprofessionelle Teams ausbauen; Schulverwaltungsassistenzen', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=47', null, 'gemischt', '2026-09-29', false, true, null),
  (4205, 4, 11, 'MV', 'Modellstudiengang „Duales Lehramt“; mehr Praxisphasen ab dem ersten Semester', '{401}', 6073, 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=55', null, 'gemischt', '2026-09-29', false, true, null),
  (4206, 4, 11, 'MV', 'Seiten- und Quereinstieg erleichtern, verpflichtende Qualifizierung beibehalten', '{401}', 6075, 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=56', null, 'gemischt', '2026-09-29', false, true, null),
  (4207, 4, 11, 'MV', 'Private Smartphone-Nutzung bis Klasse zehn auf dem gesamten Schulgelände untersagen', '{403}', 6083, 1, 3, null, 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=53', null, 'gemischt', '2026-09-29', false, true, null),
  (4208, 4, 11, 'MV', 'Schulsozialarbeit verstetigen und an sozialen Brennpunkten ausbauen', '{405}', 6078, 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=50', null, 'gemischt', '2026-09-29', false, true, null),
  (4209, 4, 11, 'MV', 'Zugang zum Gymnasium nur mit mindestens befriedigenden Leistungen oder Potenzialtest', '{403}', 6082, 1, 3, null, 'Leistungsabhängige Übergänge ins Gymnasium sollen passgenauer fördern; ob die Schulstruktur die Leistungen verbessert, ist in der Forschung nicht entschieden. Das Land kann es im Schulgesetz regeln.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=48', null, 'offen', '2026-09-29', false, true, null),
  (4210, 4, 11, 'MV', 'Zusätzliche Landesmittel für Schulsanierung neben den laufenden Programmen', '{402}', 6085, 1, 2, null, 'Mehr Tempo bei Schulsanierungen setzt am Sanierungsstau an; das Programm nennt aber weder Umfang noch Finanzierung.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=59', null, 'gemischt', '2026-09-29', false, true, null),
  (4211, 4, 12, 'MV', 'Schulbauprogramm (400 Mio. Euro) ausbauen, 600 Mio. Euro aus dem Sondervermögen; bis 2035 möglichst alle Schulen saniert', '{402}', null, 3, 3, null, 'Ein Schulbauprogramm mit benannter Finanzierung setzt direkt am Sanierungsstau an; ob bis 2035 wirklich alle Schulen saniert sind, hängt von Baukapazitäten und Kommunen ab. Die Mittel aus Landesprogramm und Sondervermögen des Bundes sind eingeplant.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=65', null, 'belegt', '2026-09-29', false, true, null),
  (4212, 4, 12, 'MV', 'Landeseigener Sozialindex: Personal und Geld dorthin, wo Schüler mehr Unterstützung brauchen', '{405}', 6071, 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=68', null, 'gemischt', '2026-09-29', false, true, null),
  (4213, 4, 12, 'MV', 'Quer- und Seiteneinstieg in Kooperation mit den Hochschulen ausbauen', '{401}', 6075, 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=68', null, 'gemischt', '2026-09-29', false, true, null),
  (4214, 4, 12, 'MV', 'Schulleitungen und Pädagogen durch zusätzliches Verwaltungsfachpersonal entlasten', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=68', null, 'gemischt', '2026-09-29', false, true, null),
  (4215, 4, 12, 'MV', 'Zusätzliche Stunden für Deutsch und Mathematik und das Leseband fortsetzen und ausbauen', '{403}', 6070, 2, 2, null, 'Mehr Unterrichtszeit für Lesen, Schreiben und Rechnen kann Basiskompetenzen stärken; Studien finden Effekte vor allem bei gezielter, gut angeleiteter Übung. Braucht zusätzliche Lehrkräftestunden, die knapp sind.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=69', null, 'gemischt', '2026-09-29', false, true, null),
  (4216, 4, 12, 'MV', 'Sprachliche Bildung in Kitas stärken, Sprach-Kitas erhalten und ausbauen', '{404}', 6077, 1, 3, null, 'Mehr Sprachförderung in Kitas setzt am Sprachförderbedarf an; ohne verbindliche Feststellung und Förderpflicht erreicht sie nicht sicher alle Kinder mit Bedarf. Das Land ist zuständig.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=65', null, 'gemischt', '2026-09-29', false, true, null),
  (4217, 4, 12, 'MV', 'Schulen in Gebieten mit besonderen Herausforderungen vorrangig zu gebundenen Ganztagsschulen', '{405}', 6080, 1, 2, null, 'Ganztag kann Kinder aus benachteiligten Familien unterstützen, Effekte auf Leistungen hängen laut Studien stark von der Qualität ab. Der Ausbau braucht Personal und Räume.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=69', null, 'gemischt', '2026-09-29', false, true, null),
  (4221, 4, 13, 'MV', 'Multiprofessionelle Teams an allen Schulen, auch mit Assistenz für Verwaltungsarbeiten', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://gruene-mv.de/?wpdmdl=33772#page=40', null, 'gemischt', '2026-09-29', false, true, null),
  (4222, 4, 13, 'MV', 'Mehr Lehramtsabsolventen: Studium praxisnäher, bessere Betreuung im Vorbereitungsdienst', '{401}', 6073, 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://gruene-mv.de/?wpdmdl=33772#page=42', null, 'gemischt', '2026-09-29', false, true, null),
  (4223, 4, 13, 'MV', 'Stipendienprogramm für Lehramtsstudierende in Mangelfächern', '{401}', 6074, 1, 2, null, 'Zulagen, Stipendien oder Verpflichtungen können Lehrkräfte in unterversorgte Regionen oder Schulen lenken; die Gesamtzahl der Lehrkräfte steigt dadurch kaum. Für das Land finanzierbar, aber mit dauerhaften Kosten.', 'https://gruene-mv.de/?wpdmdl=33772#page=42', null, 'gemischt', '2026-09-29', false, true, null),
  (4224, 4, 13, 'MV', 'Längeres gemeinsames Lernen bis Klasse 6, möglichst an einem Standort', '{405}', 6079, 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://gruene-mv.de/?wpdmdl=33772#page=43', null, 'offen', '2026-09-29', false, true, null),
  (4225, 4, 13, 'MV', 'Land beteiligt sich an den Kosten einer hochwertigen Kita- und Schulverpflegung', '{405}', 6084, 1, 2, null, 'Kostenfreies Essen und Lernmittel entlasten benachteiligte Familien; Studien finden teils positive, meist kleine Effekte auf das Lernen. Dauerhafte Kosten für das Land.', 'https://gruene-mv.de/?wpdmdl=33772#page=44', null, 'gemischt', '2026-09-29', false, true, null),
  (4231, 4, 14, 'MV', 'Lehramtsstudium für alle MINT-Fächer an der Universität Greifswald', '{401}', 6073, 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=88', null, 'gemischt', '2026-09-29', false, true, null),
  (4232, 4, 14, 'MV', 'Schulsanierungen nach landesweiter Priorisierung; kommunale Investitionen beschleunigen', '{402}', null, 1, 3, null, 'Eine Priorisierung und schnellere Verfahren setzen das vorhandene Geld gezielter ein; zusätzliches Geld für den Sanierungsstau sieht das Programm nicht vor. Für das Land umsetzbar.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=85', null, 'gemischt', '2026-09-29', false, true, null),
  (4233, 4, 14, 'MV', 'Frühzeitige Sprachförderung für alle Kinder mit Sprachdefiziten, mehr Vorlesen in Kitas', '{404}', 6077, 1, 3, null, 'Mehr Sprachförderung in Kitas setzt am Sprachförderbedarf an; ohne verbindliche Feststellung und Förderpflicht erreicht sie nicht sicher alle Kinder mit Bedarf. Das Land ist zuständig.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=82', null, 'gemischt', '2026-09-29', false, true, null),
  (4234, 4, 14, 'MV', 'Ressourcen auf Brennpunktschulen, Eingangsklassen und Sprachlernphasen konzentrieren', '{405}', 6071, 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=97', null, 'gemischt', '2026-09-29', false, true, null),
  (4235, 4, 14, 'MV', 'An jeder Schule eine Kraft für Schulsozialarbeit', '{405}', 6078, 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=97', null, 'gemischt', '2026-09-29', false, true, null),
  (4236, 4, 14, 'MV', 'Haupt- und Realschulen wieder einführen statt Regionaler Schule', '{403}', null, 1, 2, null, 'Ein stärker gegliedertes Schulangebot soll passgenauer fördern; ob die Schulstruktur die Leistungen verbessert, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=86', null, 'offen', '2026-09-29', false, true, null),
  (4241, 4, 15, 'MV', 'Rund 400 abgeordnete Lehrerstellen aus Ministerium, Schulämtern und Institut zurück an die Schulen', '{401}', null, 2, 2, null, 'Abgeordnete Lehrkräfte zurück in den Unterricht zu holen, erhöht das Angebot sofort spürbar; ihre bisherigen Aufgaben in Verwaltung und Fortbildung müssten dann andere übernehmen. Für das Land umsetzbar.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=24', null, 'gemischt', '2026-09-29', false, true, null),
  (4242, 4, 15, 'MV', 'Schulverwaltungsassistenten gegen Verwaltungslast', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=24', null, 'gemischt', '2026-09-29', false, true, null),
  (4243, 4, 15, 'MV', 'Kurzfristig geeignete Seiteneinsteiger einsetzen', '{401}', 6075, 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=25', null, 'gemischt', '2026-09-29', false, true, null),
  (4244, 4, 15, 'MV', 'Pädagogische Hochschule mit vergüteter Ausbildung und Übernahmeperspektive', '{401}', 6073, 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=25', null, 'gemischt', '2026-09-29', false, true, null),
  (4245, 4, 15, 'MV', 'Vorschule mit verbindlichem Lehrplan im letzten Kindergartenjahr', '{404}', 6086, 2, 2, null, 'Ein verbindliches Vorschuljahr kann Sprachrückstände vor der Einschulung verringern; ohne Feststellung des Förderbedarfs ist die Förderung weniger gezielt. Braucht Fachkräfte in Kitas oder Grundschulen.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=27', null, 'gemischt', '2026-09-29', false, true, null),
  (4246, 4, 15, 'MV', 'Vorschaltklassen für Kinder ohne ausreichende Deutschkenntnisse', '{404}', 6087, 1, 2, null, 'Getrennte Sprachklassen vor dem Regelunterricht können gezielt Deutsch vermitteln; Studien zu getrenntem und gemeinsamem Unterricht sind gemischt. Braucht zusätzliche Lehrkräfte.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=26', null, 'gemischt', '2026-09-29', false, true, null),
  (4247, 4, 15, 'MV', 'Aufnahme ins Gymnasium bei Noten schlechter als 2,5 nur über einen Eignungstest', '{403}', 6082, 1, 3, null, 'Leistungsabhängige Übergänge ins Gymnasium sollen passgenauer fördern; ob die Schulstruktur die Leistungen verbessert, ist in der Forschung nicht entschieden. Das Land kann es im Schulgesetz regeln.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=27', null, 'offen', '2026-09-29', false, true, null),
  (4248, 4, 15, 'MV', 'Private Handynutzung bis Klasse 7 per Verordnung unterbinden', '{403}', 6083, 1, 3, null, 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=31', null, 'gemischt', '2026-09-29', false, true, null),
  (4249, 4, 15, 'MV', 'Schulsozialarbeit als Landesaufgabe; mehr Schulpsychologen', '{405}', 6078, 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=25', null, 'gemischt', '2026-09-29', false, true, null),
  (4251, 4, 16, 'MV', '500 Alltagshilfen, 100 Verwaltungsfachkräfte, 100 Psychologen und 300 pädagogische Fachkräfte zusätzlich an Schulen', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=5', null, 'gemischt', '2026-09-29', false, true, null),
  (4252, 4, 16, 'MV', 'Flächendeckende Sprachstandsfeststellung mit viereinhalb Jahren, zusätzliche Sprachfachkräfte, verbindliches Vorschuljahr', '{404}', 6069, 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=5', null, 'gemischt', '2026-09-29', false, true, null),
  (4253, 4, 16, 'MV', 'Schulsozialarbeit an jeder Schule', '{405}', 6078, 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=5', null, 'gemischt', '2026-09-29', false, true, null),
  (4254, 4, 16, 'MV', '300-Millionen-Euro-Bildungspaket für Personal und individuelle Förderung', '{403}', null, 1, 2, null, 'Zusätzliches Geld für Personal und individuelle Förderung kann Rückstände verringern; wofür genau es eingesetzt wird, lässt das Programm offen. Die Finanzierung muss das Land im Haushalt sichern.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=5', null, 'gemischt', '2026-09-29', false, true, null),
  (4271, 4, 17, 'MV', 'Verbindliche Sprachstandsfeststellung ab vier Jahren mit gezielter Förderung; verpflichtendes Vorschuljahr', '{404}', 6069, 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=46', null, 'gemischt', '2026-09-29', false, true, null),
  (4272, 4, 17, 'MV', 'Praxisnäheres Lehramtsstudium in Richtung duales Studium, Entlastung im Referendariat, Hilfe bei der Wohnungssuche', '{401}', 6073, 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=47', null, 'gemischt', '2026-09-29', false, true, null),
  (4273, 4, 17, 'MV', 'Multiprofessionelle Teams mit Sozialarbeit, Schulpsychologie und IT-Support', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=46', null, 'gemischt', '2026-09-29', false, true, null),
  (4274, 4, 17, 'MV', 'Handys und Tablets aus den Klassenzimmern der Grundschulen verbannen', '{403}', 6083, 1, 3, null, 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=47', null, 'gemischt', '2026-09-29', false, true, null),
  (4275, 4, 17, 'MV', 'Kleinere Klassen mit höchstens 24 Schülerinnen und Schülern', '{403}', null, 1, 2, null, 'Kleinere Klassen können das Lernen verbessern; Studien finden eher kleine Effekte, größere vor allem in den ersten Schuljahren. Braucht zusätzliche Lehrkräfte, sinkende Schülerzahlen helfen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=48', null, 'gemischt', '2026-09-29', false, true, null),
  (4276, 4, 17, 'MV', 'Förderunterricht und Kursangebote für Kinder aus benachteiligten Milieus ausbauen', '{405}', null, 1, 2, null, 'Zusätzlicher Förderunterricht für benachteiligte Kinder kann Rückstände verringern; Studien zu gezielter Förderung in kleinen Gruppen zeigen positive Effekte, das Programm nennt aber keinen Umfang. Braucht zusätzliche Lehrkräftestunden.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=48', null, 'gemischt', '2026-09-29', false, true, null),
  (4277, 4, 17, 'MV', 'Zugang zum Gymnasium über bindende Laufbahnempfehlung oder Aufnahmeprüfung', '{403}', 6082, 1, 3, null, 'Leistungsabhängige Übergänge ins Gymnasium sollen passgenauer fördern; ob die Schulstruktur die Leistungen verbessert, ist in der Forschung nicht entschieden. Das Land kann es im Schulgesetz regeln.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=49', null, 'offen', '2026-09-29', false, true, null),
  (4301, 4, 11, 'BE', 'Schulbauoffensive fortführen; Programm für kleinteilige Sanierungen', '{402}', 6076, 2, 2, null, 'Ein Schulbauprogramm setzt direkt am Sanierungsstau an; wie weit es reicht, hängt von Umfang, Baukapazitäten und Kommunen ab. Das Programm nennt keinen Betrag, die Finanzierung muss das Land im Haushalt sichern.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=59', null, 'belegt', '2026-09-29', false, true, null),
  (4302, 4, 11, 'BE', 'Berufsbegleitende Qualifizierung von Quereinsteigern; Ein-Fach-Lehrkraft, Tandemlehrer, Flex-Master', '{401}', 6075, 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=58', null, 'gemischt', '2026-09-29', false, true, null),
  (4303, 4, 11, 'BE', 'Lehrkräfte verbeamten', '{401}', null, 1, 2, null, 'Verbeamtung macht den Lehrerberuf im Wettbewerb der Länder attraktiver; die Gesamtzahl der Lehrkräfte steigt dadurch nicht, und die Pensionslasten sind hoch.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=58', null, 'gemischt', '2026-09-29', false, true, null),
  (4304, 4, 11, 'BE', 'Freiwillige Ferienschulen zum Aufholen von Rückständen in Lesen, Schreiben und Rechnen', '{403}', null, 2, 3, null, 'Ferienschulen können Lernrückstände gezielt aufholen; Studien zu Lernferien finden positive Effekte, freiwillige Angebote erreichen aber nicht alle Kinder mit Bedarf. Das Land kann sie selbst organisieren.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=55', null, 'gemischt', '2026-09-29', false, true, null),
  (4305, 4, 11, 'BE', 'Vorschule (Kita-Chancenjahr) mit Schwerpunkt Sprachförderung', '{404}', 6086, 2, 2, null, 'Ein verbindliches Vorschuljahr kann Sprachrückstände vor der Einschulung verringern; ohne Feststellung des Förderbedarfs ist die Förderung weniger gezielt. Braucht Fachkräfte in Kitas oder Grundschulen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=56', null, 'gemischt', '2026-09-29', false, true, null),
  (4306, 4, 11, 'BE', 'Landesprogramm Schulsozialarbeit stärken', '{405}', 6078, 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=58', null, 'gemischt', '2026-09-29', false, true, null),
  (4311, 4, 12, 'BE', 'Verpflichtende Sprachstandsfeststellungen, gezielte Förderung vor der Einschulung', '{404}', 6069, 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=38', null, 'gemischt', '2026-09-29', false, true, null),
  (4312, 4, 12, 'BE', 'Personalzuschlag für Schülerinnen und Schüler nicht deutscher Herkunftssprache wieder einführen', '{405}', 6071, 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=37', null, 'gemischt', '2026-09-29', false, true, null),
  (4313, 4, 12, 'BE', 'Schulbauoffensive fortsetzen, Schwerpunkt auf Sanierung der Bestandsgebäude', '{402}', 6076, 2, 2, null, 'Ein Schulbauprogramm setzt direkt am Sanierungsstau an; wie weit es reicht, hängt von Umfang, Baukapazitäten und Kommunen ab. Das Programm nennt keinen Betrag, die Finanzierung muss das Land im Haushalt sichern.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=42', null, 'belegt', '2026-09-29', false, true, null),
  (4314, 4, 12, 'BE', 'Nichtpädagogisches Personal ausbauen: Verwaltungsleitungen, IT-Personal, Hausmeister', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=42', null, 'gemischt', '2026-09-29', false, true, null),
  (4315, 4, 12, 'BE', 'Anerkennung von Lehrkräften mit internationalen Qualifikationen erleichtern', '{401}', 6088, 2, 3, null, 'Leichtere Anerkennung ausländischer Lehrkräfte (etwa mit nur einem Fach) erschließt kurzfristig zusätzliche Bewerberinnen und Bewerber; ihre Zahl ist begrenzt, das Sprachniveau bleibt eine Hürde. Das Land ist zuständig.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=42', null, 'gemischt', '2026-09-29', false, true, null),
  (4316, 4, 12, 'BE', 'Handyverbot an allen Grundschulen', '{403}', 6083, 1, 3, null, 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', null, 'gemischt', '2026-09-29', false, true, null),
  (4317, 4, 12, 'BE', 'Zahl der Gemeinschaftsschulen verdoppeln', '{405}', 6079, 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=39', null, 'offen', '2026-09-29', false, true, null),
  (4318, 4, 12, 'BE', 'Landesprogramm Schulstationen; mindestens eine Schulsozialarbeiterstelle je Schule', '{405}', 6078, 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=42', null, 'gemischt', '2026-09-29', false, true, null),
  (4319, 4, 12, 'BE', 'Flex-Ganztag an Grundschulen bis Klasse 6 ausbauen', '{405}', 6080, 1, 2, null, 'Ganztag kann Kinder aus benachteiligten Familien unterstützen, Effekte auf Leistungen hängen laut Studien stark von der Qualität ab. Der Ausbau braucht Personal und Räume.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=40', null, 'gemischt', '2026-09-29', false, true, null),
  (4321, 4, 13, 'BE', 'Nach Hamburger Vorbild verbindliche Förderung nach der Sprachstandserhebung bei Vierjährigen', '{404}', 6069, 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=183', null, 'gemischt', '2026-09-29', false, true, null),
  (4322, 4, 13, 'BE', 'Lehrkräften mit internationalen Abschlüssen den Zugang erleichtern: Ein-Fach-Lehrkraft, einfachere Anerkennung, kostenlose Deutschkurse', '{401}', 6088, 2, 3, null, 'Leichtere Anerkennung ausländischer Lehrkräfte (etwa mit nur einem Fach) erschließt kurzfristig zusätzliche Bewerberinnen und Bewerber; ihre Zahl ist begrenzt, das Sprachniveau bleibt eine Hürde. Das Land ist zuständig.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=194', null, 'gemischt', '2026-09-29', false, true, null),
  (4323, 4, 13, 'BE', 'Stipendium für Lehramtsstudierende, die fünf Jahre an unterversorgten Schulen arbeiten', '{401}', 6074, 1, 2, null, 'Zulagen, Stipendien oder Verpflichtungen können Lehrkräfte in unterversorgte Regionen oder Schulen lenken; die Gesamtzahl der Lehrkräfte steigt dadurch kaum. Für das Land finanzierbar, aber mit dauerhaften Kosten.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=194', null, 'gemischt', '2026-09-29', false, true, null),
  (4324, 4, 13, 'BE', 'Teams aus verschiedenen Professionen an allen Schulen', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=193', null, 'gemischt', '2026-09-29', false, true, null),
  (4325, 4, 13, 'BE', 'Einstellungskontingente und Mindestausstattung mit qualifizierten Lehrkräften für Schulen in herausfordernden Lagen', '{405}', 6071, 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=194', null, 'gemischt', '2026-09-29', false, true, null),
  (4326, 4, 13, 'BE', 'Sanierung alter Schulgebäude vorantreiben', '{402}', 6085, 1, 2, null, 'Mehr Tempo bei Schulsanierungen setzt am Sanierungsstau an; das Programm nennt aber weder Umfang noch Finanzierung.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=192', null, 'gemischt', '2026-09-29', false, true, null),
  (4327, 4, 13, 'BE', 'Zahl der Gemeinschaftsschulen verdoppeln', '{405}', 6079, 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=187', null, 'offen', '2026-09-29', false, true, null),
  (4328, 4, 13, 'BE', 'Mehr Schulsozialarbeiterinnen und Schulsozialarbeiter', '{405}', 6078, 1, 3, null, 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=189', null, 'gemischt', '2026-09-29', false, true, null),
  (4331, 4, 14, 'BE', 'Schulpflichtiges Vorschuljahr in der Kita; verbindliche Sprachstandstests mit drei bis vier Jahren', '{404}', 6069, 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=6', null, 'gemischt', '2026-09-29', false, true, null),
  (4332, 4, 14, 'BE', 'Personal für die Schulverwaltung verbessern, um Lehrkräfte zu entlasten', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=8', null, 'gemischt', '2026-09-29', false, true, null),
  (4333, 4, 14, 'BE', 'Fester Schultag im Lehramtsstudium; langfristig alle Lehramtsstudiengänge dual', '{401}', 6073, 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=10', null, 'gemischt', '2026-09-29', false, true, null),
  (4334, 4, 14, 'BE', 'Anreize wie Aufstiegsmöglichkeiten für ausgebildete Lehrkräfte an Brennpunktschulen', '{405}', null, 1, 3, null, 'Anreize für voll ausgebildete Lehrkräfte an Brennpunktschulen setzen an der ungleichen Verteilung an; wie viele Lehrkräfte sich dadurch umentscheiden, ist offen. Für das Land umsetzbar.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=10', null, 'gemischt', '2026-09-29', false, true, null),
  (4341, 4, 15, 'BE', 'Pflicht zur Sprachstandsfeststellung und Sprachförderung im Kita-Alter konsequenter umsetzen', '{404}', 6069, 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=28', null, 'gemischt', '2026-09-29', false, true, null),
  (4342, 4, 15, 'BE', 'Spezialklassen für Kinder mit Sprachförderbedarf („Deutsch-Garantie-Klassen“) ausweiten', '{404}', 6087, 1, 2, null, 'Getrennte Sprachklassen vor dem Regelunterricht können gezielt Deutsch vermitteln; Studien zu getrenntem und gemeinsamem Unterricht sind gemischt. Braucht zusätzliche Lehrkräfte.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=29', null, 'gemischt', '2026-09-29', false, true, null),
  (4343, 4, 15, 'BE', 'Keine weitere Verschiebung geplanter Schulsanierungen und Schulneubauten', '{402}', 6085, 1, 2, null, 'Mehr Tempo bei Schulsanierungen setzt am Sanierungsstau an; das Programm nennt aber weder Umfang noch Finanzierung.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=29', null, 'gemischt', '2026-09-29', false, true, null),
  (4344, 4, 15, 'BE', 'Grundschule bildschirmfrei, Smartphone-Verbot', '{403}', 6083, 1, 3, null, 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=30', null, 'gemischt', '2026-09-29', false, true, null),
  (4345, 4, 15, 'BE', 'Stipendien für Lehramtsstudienanfänger in Mangelfächern mit Verpflichtung für Berlin', '{401}', 6074, 1, 2, null, 'Zulagen, Stipendien oder Verpflichtungen können Lehrkräfte in unterversorgte Regionen oder Schulen lenken; die Gesamtzahl der Lehrkräfte steigt dadurch kaum. Für das Land finanzierbar, aber mit dauerhaften Kosten.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=38', null, 'gemischt', '2026-09-29', false, true, null),
  (4346, 4, 15, 'BE', 'Einphasige Lehrerausbildung als duales Studium', '{401}', 6073, 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=39', null, 'gemischt', '2026-09-29', false, true, null),
  (4347, 4, 15, 'BE', 'Vollständige Lernmittelfreiheit, kostenloses Schulmittagessen beibehalten', '{405}', 6084, 1, 2, null, 'Kostenfreies Essen und Lernmittel entlasten benachteiligte Familien; Studien finden teils positive, meist kleine Effekte auf das Lernen. Dauerhafte Kosten für das Land.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=29', null, 'gemischt', '2026-09-29', false, true, null),
  (4351, 4, 16, 'BE', 'Zusätzliche Mittel für die Lehrkräftebildung, Ziel 3.000 Absolventen im Jahr; Kapazitäten gesetzlich am Bedarf ausrichten', '{401}', 6073, 2, 2, null, 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=225', null, 'gemischt', '2026-09-29', false, true, null),
  (4352, 4, 16, 'BE', 'Quereinstieg öffnen, auch mit nur einem Fach', '{401}', 6075, 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=228', null, 'gemischt', '2026-09-29', false, true, null),
  (4353, 4, 16, 'BE', 'Ausländische Lehramtsabschlüsse leichter anerkennen, Einstellung mit einem Fach, Sprachanforderung C1', '{401}', 6088, 2, 3, null, 'Leichtere Anerkennung ausländischer Lehrkräfte (etwa mit nur einem Fach) erschließt kurzfristig zusätzliche Bewerberinnen und Bewerber; ihre Zahl ist begrenzt, das Sprachniveau bleibt eine Hürde. Das Land ist zuständig.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=155', null, 'gemischt', '2026-09-29', false, true, null),
  (4354, 4, 16, 'BE', 'Je Schule eine volle Stelle für Verwaltungsleitung und IT-Administration; mehr Unterrichtshilfen und Schulassistenz', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=155', null, 'gemischt', '2026-09-29', false, true, null),
  (4355, 4, 16, 'BE', 'Schulbauoffensive fortsetzen und beschleunigen', '{402}', 6076, 2, 2, null, 'Ein Schulbauprogramm setzt direkt am Sanierungsstau an; wie weit es reicht, hängt von Umfang, Baukapazitäten und Kommunen ab. Das Programm nennt keinen Betrag, die Finanzierung muss das Land im Haushalt sichern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=169', null, 'belegt', '2026-09-29', false, true, null),
  (4356, 4, 16, 'BE', 'Handyfreier Schultag bis Klasse 9 als Grundsatz', '{403}', 6083, 1, 3, null, 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=167', null, 'gemischt', '2026-09-29', false, true, null),
  (4357, 4, 16, 'BE', 'Allen Kindern mindestens 24 Monate Kita vor der Einschulung ermöglichen', '{404}', null, 1, 2, null, 'Ein längerer Kitabesuch verbessert nachweislich die Sprachkenntnisse bei der Einschulung; ohne Pflicht und gezielte Förderung erreicht er aber nicht sicher alle Kinder mit Bedarf. Braucht zusätzliche Kitaplätze und Fachkräfte.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=188', null, 'gemischt', '2026-09-29', false, true, null),
  (4358, 4, 16, 'BE', 'Ergänzungsbudget für Schulen in schwieriger Lage fortsetzen, Startchancen-Mittel zielgenau einsetzen', '{405}', 6071, 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=157', null, 'gemischt', '2026-09-29', false, true, null),
  (4359, 4, 16, 'BE', 'Gemeinschaftsschulen deutlich ausbauen, mindestens zwei neue je Bezirk bis 2031', '{405}', 6079, 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=153', null, 'offen', '2026-09-29', false, true, null),
  (4360, 4, 16, 'BE', 'Lernmittelfreiheit und kostenloses Mittagessen auf Mittel- und Oberstufe ausweiten', '{405}', 6084, 1, 2, null, 'Kostenfreies Essen und Lernmittel entlasten benachteiligte Familien; Studien finden teils positive, meist kleine Effekte auf das Lernen. Dauerhafte Kosten für das Land.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=153', null, 'gemischt', '2026-09-29', false, true, null),
  (4361, 4, 17, 'BE', 'Verbindliche Vorschulphase mit Sprachbildung', '{404}', 6086, 2, 2, null, 'Ein verbindliches Vorschuljahr kann Sprachrückstände vor der Einschulung verringern; ohne Feststellung des Förderbedarfs ist die Förderung weniger gezielt. Braucht Fachkräfte in Kitas oder Grundschulen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=14', null, 'gemischt', '2026-09-29', false, true, null),
  (4362, 4, 17, 'BE', 'Mehrjähriges Förderprogramm für Schulen in Brennpunktlagen mit Mitteln und voll ausgebildetem Personal', '{405}', 6071, 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=14', null, 'gemischt', '2026-09-29', false, true, null),
  (4363, 4, 17, 'BE', 'Breites Angebot an Gemeinschaftsschulen', '{405}', 6079, 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=15', null, 'offen', '2026-09-29', false, true, null),
  (4364, 4, 17, 'BE', 'Multiprofessionelle Teams mit Fachkräften für IT und Verwaltung', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=16', null, 'gemischt', '2026-09-29', false, true, null),
  (4365, 4, 17, 'BE', 'Smartphones im Unterricht grundsätzlich nicht nutzen und wegschließen', '{403}', 6083, 1, 3, null, 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=16', null, 'gemischt', '2026-09-29', false, true, null),
  (4366, 4, 17, 'BE', 'Sanierungen in klaren Fristen, Hausmeisterwesen für die Wartung', '{402}', 6085, 1, 2, null, 'Mehr Tempo bei Schulsanierungen setzt am Sanierungsstau an; das Programm nennt aber weder Umfang noch Finanzierung.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=17', null, 'gemischt', '2026-09-29', false, true, null),
  (8473, 4, 18, null, 'Duales Lehramtsstudium, das auch ausländische Abschlüsse und pädagogische Praxis anerkennt.', '{401}', null, 2, 2, null, 'Ein praxisintegriertes Lehramtsstudium mit Anrechnung ausländischer Abschlüsse kann zusätzliche Lehrkräfte gewinnen; zu dualen Lehramtsmodellen gibt es erst wenige Befunde. Lehrerbildung ist Ländersache, der Bund kann nur über Förderprogramme beitragen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=115', null, 'offen', '2026-10-07', false, true, 'blind'),
  (8474, 4, 18, null, 'Lehrkräfte durch Verwaltungsfachkräfte und multiprofessionelle Teams entlasten.', '{401}', null, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zeigen Entlastung, Lerneffekte aber nur bei gezieltem Einsatz. Schulpersonal ist Ländersache, der Bund kann nur über Programme mitfinanzieren.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=107', 'https://evidenceforlearning.org.au/toolkit/teaching-assistants', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8475, 4, 18, null, 'Bundesweiter Bildungskanon für das Vorschuljahr, der Deutsch als Schulsprache und bilinguale Betreuung fördert.', '{404}', null, 1, 2, null, 'Ein gemeinsamer Bildungsrahmen für das Vorschuljahr kann Sprachförderung vereinheitlichen; ohne Sprachstandsfeststellung und Förderpflicht erreicht er nicht sicher alle Kinder mit Bedarf, Sprachförderprogramme wirken unterschiedlich. Der Bund braucht die Länder.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=108', null, 'gemischt', '2026-10-07', false, true, 'blind'),
  (8476, 4, 18, null, 'Längeres gemeinsames Lernen: Dreigliedriges Schulsystem wird aufgehoben.', '{405}', null, 2, 1, null, 'Längeres gemeinsames Lernen setzt an der frühen Trennung an; eine Studie zu deutschen Ländern findet Gewinne für Leistungsschwächere, die Forschung zur Schulstruktur ist insgesamt aber uneinheitlich. Für die Schulstruktur ist der Bund nicht zuständig (Grundgesetzänderung).', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=110', 'https://www.diw.de/de/diw_01.c.610091.de/publikationen/diskussionspapiere/2018_1775/better_together__heterogeneous_effects_of_tracking_on_student_achievement.html', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8477, 4, 18, null, 'Lernmaterialien für schulpflichtige Kinder bundesweit kostenfrei, vom Bund finanziert.', '{405}', null, 1, 2, null, 'Kostenfreie Lernmittel entlasten vor allem einkommensschwache Familien; Studien zu kostenlosen Schulbüchern finden im Durchschnitt kaum Effekte auf Leistungen. Schulen sind Ländersache, der Bund kann nur über Vereinbarung und Finanztransfers beitragen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=105', 'https://www.povertyactionlab.org/node/1436', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8478, 4, 18, null, 'Psychologie, Schulsozialarbeit, Schulgesundheit und Sonderpädagogik als fester Teil der Schulen.', '{405}', null, 1, 2, null, 'Fachkräfte für Psychologie, Sozialarbeit und Sonderpädagogik unterstützen Kinder in schwierigen Lagen; Studien finden kleine positive Effekte von Schulberatung, sonst sind Wirkungen auf Leistungen kaum belegt. Schulpersonal ist Ländersache, der Bund kann nur mitfinanzieren.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=111', 'https://ideas.repec.org/p/pit/wpaper/396.html', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8696, 4, 18, 'BE', 'Lehrkräfte langfristiger gewinnen, Ausbildungs- und Qualifizierungswege ausbauen und den Quereinstieg bedarfsorientiert gestalten und pädagogisch begleiten.', '{401}', 6075, 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=46', null, 'gemischt', '2026-10-08', false, true, null),
  (8697, 4, 18, 'BE', 'Sanierung und Modernisierung der Schulen beschleunigen und verlässlich in Gebäude, Lernräume und Ausstattung investieren.', '{402}', 6076, 2, 2, null, 'Ein Schulbauprogramm setzt direkt am Sanierungsstau an; wie weit es reicht, hängt von Umfang, Baukapazitäten und Kommunen ab. Das Programm nennt keinen Betrag, die Finanzierung muss das Land im Haushalt sichern.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=46', null, 'belegt', '2026-10-08', false, true, null),
  (8698, 4, 18, 'BE', 'Verbindliche Sprachtests mit vier Jahren, verknüpft mit gezielter Förderung durch qualifizierte Sprachlehrkräfte.', '{404}', 6069, 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=45', null, 'gemischt', '2026-10-08', false, true, null),
  (8699, 4, 18, 'BE', 'Kitabesuch ab dem dritten Lebensjahr gezielt fördern; Kitas in Quartieren mit hohem Bedarf beim Platzausbau bevorzugen.', '{404}', 8694, 2, 2, null, 'Kitabesuch ab drei verbessert die Schulfähigkeit benachteiligter und zugewanderter Kinder deutlich; wie der Besuch gefördert wird, bleibt offen. Der Ausbau braucht Fachkräfte, die knapp sind.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=45', 'https://iab.de/en/publications/publication/?id=8487991', 'belegt', '2026-10-08', false, true, 'blind'),
  (8700, 4, 18, 'BE', 'Mehrjähriges Turnaround-Programm für die am stärksten belasteten Schulen mit zusätzlichem Personal, stärkeren Schulleitungen und Ergebnisverantwortung.', '{405}', 6071, 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=46', null, 'gemischt', '2026-10-08', false, true, null),
  (8701, 4, 18, 'MV', 'Verbindlicher Lehrer-Schüler-Schlüssel mit klaren personellen Standards für Schulen', '{401}', null, 1, 1, null, 'Kleinere Klassen können Leistungen verbessern, Studien sind aber uneinheitlich. Ein verbindlicher Schlüssel schafft keine Lehrkräfte, sondern erhöht bei bestehendem Mangel den Bedarf; das Personal fehlt absehbar.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=12', 'https://wol.iza.org/articles/class-size-does-it-matter-for-student-achievement/lang/de', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8702, 4, 18, 'MV', 'Lehrkräfte von nichtpädagogischen Aufgaben entlasten durch Digitalisierung und zusätzliche Verwaltungs- und Unterstützungsstellen', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=12', null, 'gemischt', '2026-10-08', false, true, null),
  (8703, 4, 18, 'MV', 'Verbindliche, kontinuierliche Sprachförderung in der Kita durch zusätzliche Fachkräfte', '{404}', 6077, 1, 3, null, 'Mehr Sprachförderung in Kitas setzt am Sprachförderbedarf an; ohne verbindliche Feststellung und Förderpflicht erreicht sie nicht sicher alle Kinder mit Bedarf. Das Land ist zuständig.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=10', null, 'gemischt', '2026-10-08', false, true, null),
  (8704, 4, 18, 'MV', 'Flächendeckende Erhebung und gezielte Förderung von sprachlichen und mathematischen Defiziten, möglichst vor der Einschulung', '{404,403}', 8695, 2, 2, null, 'Frühe Erhebung mit gezielter Förderung setzt an Sprach- und Rechenrückständen vor Schulbeginn an; Studien zu vorschulischen Förderprogrammen zeigen unterschiedlich starke Effekte. Braucht Fachkräfte für die Förderung.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=11', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (8705, 4, 18, 'MV', 'Dreigliedriges Schulsystem langfristig abschaffen zugunsten einer inklusiven Schule für alle', '{405}', 6079, 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=11', null, 'offen', '2026-10-08', false, true, null),
  (8706, 4, 18, 'MV', 'Schulhefte und Schulbücher werden von der Schule gestellt, damit Familien keine Zusatzkosten tragen', '{405}', 6084, 1, 2, null, 'Kostenfreies Essen und Lernmittel entlasten benachteiligte Familien; Studien finden teils positive, meist kleine Effekte auf das Lernen. Dauerhafte Kosten für das Land.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=9', null, 'gemischt', '2026-10-08', false, true, null),
  (8707, 4, 18, 'ST', 'Beruf der Lehrkraft attraktiver machen: Teamzeiten im Stundenmodell, Entlastung durch Verwaltungs- und IT-Stellen, Abschaffung dauerhafter Mehrarbeit, verbindlicher Lehrer-Schüler-Schlüssel', '{401}', null, 2, 2, null, 'Entlastung und praxisnähere Ausbildung können den Beruf attraktiver machen und Abwanderung bremsen; weniger Mehrarbeit und ein fester Schlüssel erhöhen aber zunächst den Bedarf an Lehrkräften.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=22', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (8708, 4, 18, 'ST', 'Verbindliche Sprachstandserhebungen vor der Einschulung einführen und frühe Förderung sicherstellen', '{404}', 6069, 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=19', null, 'gemischt', '2026-10-08', false, true, null),
  (8709, 4, 18, 'ST', 'Sprachförderung und Sprach-Kitas dauerhaft absichern, Kita stärker auf Schulfähigkeit ausrichten', '{404}', 6077, 1, 3, null, 'Mehr Sprachförderung in Kitas setzt am Sprachförderbedarf an; ohne verbindliche Feststellung und Förderpflicht erreicht sie nicht sicher alle Kinder mit Bedarf. Das Land ist zuständig.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=14', null, 'gemischt', '2026-10-08', false, true, null),
  (8710, 4, 18, 'ST', 'Schulen in herausfordernden Lagen gezielt besser ausstatten', '{405}', 6071, 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=19', null, 'gemischt', '2026-10-08', false, true, null),
  (8711, 4, 18, 'ST', 'Kostenfreie schulische Förder- und Nachhilfeangebote flächendeckend einrichten', '{403}', 8693, 2, 2, null, 'Nachhilfe in Kleingruppen verbessert Leistungen laut Metaanalysen deutlich, vor allem in der Schule und durch geschultes Personal; Umfang und Form sind offen, Personal und dauerhafte Kosten sind die Hürde.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=19', 'https://www.nber.org/papers/w27476', 'belegt', '2026-10-08', false, true, 'blind');

